void unit_test_update_non_head_node_only_ct(void) {
    // Setup: Build a linked list with at least two nodes.
    // Path conditions:
    // 1. ptr != NULL && ptr->ID != id (head node ID does NOT match target id)
    // 2. ct != 0 (update CT)
    // 3. wt == 0 (do NOT update WT)
    // 4. tat == 0 (do NOT update TAT)
    // This path traverses the list (loop exit) and updates only CT.

    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;

    struct node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial CT, WT, TAT are zero (as set by insert)
    struct node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(0, ptr->CT);
        TEST_ASSERT_EQUAL_INT(0, ptr->WT);
        TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        ptr = ptr->next;
    }

    // Target: Update node with ID 2 (non-head) with only CT non-zero.
    int target_id = 2;
    int new_ct = 100;
    int new_wt = 0;
    int new_tat = 0;

    update(&root, target_id, new_ct, new_wt, new_tat);

    // Assertions: Verify only CT of node ID 2 is updated.
    ptr = root;
    while (ptr != NULL) {
        if (ptr->ID == target_id) {
            TEST_ASSERT_EQUAL_INT(new_ct, ptr->CT);
            TEST_ASSERT_EQUAL_INT(0, ptr->WT);
            TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        } else {
            // Other nodes remain unchanged.
            TEST_ASSERT_EQUAL_INT(0, ptr->CT);
            TEST_ASSERT_EQUAL_INT(0, ptr->WT);
            TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        }
        ptr = ptr->next;
    }

    // Cleanup
    helper_cleanup_process_queue(&root);
